function clamp(value, min, max) {
  return Math.min(max, Math.max(min, Number(value)));
}

export function normalizeBackHairMeshSettings(settings = {}) {
  return {
    width: clamp(settings.width ?? 1, 0.5, 1.8),
    depth: clamp(settings.depth ?? 1, 0.5, 1.8),
    thickness: clamp(settings.thickness ?? 0.1, 0, 0.3),
    headFit: clamp(settings.headFit ?? 1, 0, 1),
    crownHeight: clamp(settings.crownHeight ?? 1, 0.6, 1.6),
    backProjection: clamp(settings.backProjection ?? 1, 0.5, 1.8),
    napeLength: clamp(settings.napeLength ?? 1, 0.5, 1.8),
    lowerFlare: clamp(settings.lowerFlare ?? 0, -0.5, 1)
  };
}

function solidifyQuadSurface(points, faces, faceZones, thickness) {
  if (thickness <= 0.000001) {
    return {
      points,
      faces,
      faceZones
    };
  }
  const normals = points.map(() => ({ x: 0, y: 0, z: 0 }));
  const edges = new Map();
  faces.forEach((face, faceIndex) => {
    const origin = points[face[0]];
    for (let index = 1; index < face.length - 1; index += 1) {
      const pointA = points[face[index]];
      const pointB = points[face[index + 1]];
      const ax = pointA.x - origin.x;
      const ay = pointA.y - origin.y;
      const az = pointA.z - origin.z;
      const bx = pointB.x - origin.x;
      const by = pointB.y - origin.y;
      const bz = pointB.z - origin.z;
      const cross = {
        x: ay * bz - az * by,
        y: az * bx - ax * bz,
        z: ax * by - ay * bx
      };
      face.forEach((vertexIndex) => {
        normals[vertexIndex].x += cross.x;
        normals[vertexIndex].y += cross.y;
        normals[vertexIndex].z += cross.z;
      });
    }
    face.forEach((a, edgeIndex) => {
      const b = face[(edgeIndex + 1) % face.length];
      const key = a < b ? `${a}:${b}` : `${b}:${a}`;
      const edge = edges.get(key);
      if (edge) edge.count += 1;
      else edges.set(key, { a, b, count: 1, zone: faceZones[faceIndex] });
    });
  });
  normals.forEach((normal) => {
    const length = Math.hypot(normal.x, normal.y, normal.z) || 1;
    normal.x /= length;
    normal.y /= length;
    normal.z /= length;
  });
  const innerOffset = points.length;
  const solidPoints = [
    ...points,
    ...points.map((point, index) => ({
      x: point.x + normals[index].x * thickness,
      y: point.y + normals[index].y * thickness,
      z: point.z + normals[index].z * thickness
    }))
  ];
  const innerFaces = faces.map((face) => [...face].reverse());
  const outerFaces = faces.map((face) => face.map((index) => index + innerOffset));
  const sideFaces = [];
  const sideZones = [];
  edges.forEach((edge) => {
    if (edge.count !== 1) return;
    sideFaces.push([edge.a, edge.b, edge.b + innerOffset, edge.a + innerOffset]);
    sideZones.push(edge.zone);
  });
  return {
    points: solidPoints,
    faces: [...innerFaces, ...outerFaces, ...sideFaces],
    faceZones: [...faceZones, ...faceZones, ...sideZones]
  };
}

export function createBackHairMeshData(settings = {}) {
  const normalized = normalizeBackHairMeshSettings(settings);
  const sourceHeight = 168.910492 - SOURCE_MIN_Y;
  const vertexZoneWeights = SOURCE_VERTICES.map(() => [0, 0, 0]);
  SOURCE_FACE_DATA.forEach(([face, zone]) => face.forEach((index) => { vertexZoneWeights[index][zone] += 1; }));
  const points = SOURCE_VERTICES.map(([sourceX, sourceY, sourceZ], index) => {
    const closeFit = CLOSE_FIT_VERTICES[index];
    const blendedX = sourceX + (closeFit[0] - sourceX) * normalized.headFit;
    const blendedY = sourceY + (closeFit[1] - sourceY) * normalized.headFit;
    const blendedZ = sourceZ + (closeFit[2] - sourceZ) * normalized.headFit;
    const y01 = (sourceY - SOURCE_MIN_Y) / sourceHeight;
    const lowerWeight = (1 - y01) ** 2;
    const upperWeight = y01 ** 2;
    const weights = vertexZoneWeights[index];
    const totalWeight = Math.max(1, weights[0] + weights[1] + weights[2]);
    const rearWeight = (weights[1] * 0.45 + weights[2]) / totalWeight;
    const x = blendedX * SOURCE_SCALE * normalized.width * (1 + normalized.lowerFlare * lowerWeight);
    let y = (blendedY - SOURCE_CENTER_Y) * SOURCE_SCALE + 0.55 + BACK_HAIR_MESH_INTERNAL_Y_OFFSET;
    y += (normalized.crownHeight - 1) * upperWeight * 0.75;
    y -= (normalized.napeLength - 1) * lowerWeight * 0.75;
    let z = blendedZ * SOURCE_SCALE * normalized.depth;
    if (z < 0) z *= 1 + (normalized.backProjection - 1) * rearWeight;
    return { x, y, z };
  });
  const faces = SOURCE_FACE_DATA.map(([face]) => [...face]);
  const faceZones = SOURCE_FACE_DATA.map(([, zone]) => zone);
  const solid = solidifyQuadSurface(points, faces, faceZones, normalized.thickness);
  return {
    settings: normalized,
    ...solid
  };
}

export function backHairMeshTopologySummary(settings = {}) {
  const data = createBackHairMeshData(settings);
  const edges = new Map();
  data.faces.forEach((face) => face.forEach((a, index) => {
    const b = face[(index + 1) % face.length];
    const key = a < b ? `${a}:${b}` : `${b}:${a}`;
    edges.set(key, (edges.get(key) || 0) + 1);
  }));
  return {
    vertexCount: data.points.length,
    faceCount: data.faces.length,
    quadCount: data.faces.filter((face) => face.length === 4).length,
    boundaryEdgeCount: [...edges.values()].filter((count) => count === 1).length,
    nonManifoldEdgeCount: [...edges.values()].filter((count) => count > 2).length
  };
}
